                document.getElementById('status-hair-accessory').innerText = GetNewValue(SafeGetValue(hotaruData, '著裝.髮飾'));
                document.getElementById('status-bracelet').innerText = GetNewValue(SafeGetValue(hotaruData, '著裝.手環'));
                document.getElementById('status-gloves').innerText = GetNewValue(SafeGetValue(hotaruData, '著裝.手套'));
                document.getElementById('status-jewelry').innerText = GetNewValue(SafeGetValue(hotaruData, '著裝.首飾'));
